 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Lucy. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "I am absolutely livid! My latest bill is completely wrong. I've been overcharged by forty dollars and I want it fixed right now!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I need your account number and date of birth to access your records.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Fine. My account number is 55372513 and my date of birth is 10/12/1997. My name is Karan Brown and my phone is 91366 11830.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "I see the error. There was a duplicate charge for the premium data package.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "This is ridiculous. Why does this keep happening? I'm tired of these mistakes!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I can assure you there won't be any more outages in your area.",
      "tags": [
        "prohibited_promise"
      ]
    },
    {
      "speaker": "customer",
      "text": "What does that have to do with my bill? Just give me my money back!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will raise a refund request for the wrong charge now.",
      "tags": [
        "action:refund_request"
      ]
    },
    {
      "speaker": "customer",
      "text": "Thank you. Will it be back in my account immediately?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "The refund is subject to approval and will take 7-10 business days to process.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "Okay, that's fair enough. I appreciate you sorting this out for me.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Is there anything else I can help you with? I have submitted the refund request and it will be processed within the timeframe mentioned. Goodbye.",
      "tags": [
        "closure"
      ]
    },
    {
      "speaker": "customer",
      "text": "No, that's all. Thanks, Lucy. Bye!",
      "tags": []
    }
  ]
}
